  "established": "∀ n : Nat, n < 6 → (n * n) % 4 ≠ 2",
  "proof_body": "begin
  intro n, intro h, cases n with n, swap, { cases n, { rw Nat.zero_mod, refl }, { rw Nat.one_mod, refl } },
  { cases n, { rw Nat.two_mod, refl }, { rw Nat.three_mod, refl } },
  { cases n, { rw Nat.three_mod, refl }, { rw Nat.four_mod, refl } },
  { rw Nat.five_mod, refl }
end",
  "report": "Established that for all natural numbers n less than 6, the square of n modulo 4 is not equal to 2."
}

