{
  "established": "∀ n : Nat, n < 6 → (n * n) % 4 = 0",
  "proof_body": "begin
  induction n with d hd,
  { -- n = 0
    simp [Nat.zero_mul, Nat.mod_eq_self],
  },
  { -- n = succ d
    cases d with d',
    { -- d = 0, n = 1
      simp [Nat.one_mul, Nat.mod_eq_self],
    },
    { -- d = succ d', n = succ (succ d') = 2 + d'
      cases d' with d'',
      { -- d' = 0, n = 2
        simp [Nat.two_mul, Nat.mod_eq_self],
      },
      { -- d' = succ d'', n = 3 + d''
        cases d'' with d''',
        { -- d'' = 0, n = 3
          simp [Nat.three_mul, Nat.mod_eq_self],
        },
        { -- d'' = succ d''', n = 4 + d'''
          cases d''' with d'''',
          { -- d''' = 0, n = 4
            simp [Nat.four_mul, Nat.mod_eq_self],
          },
          { -- d''' = succ d'''', n = 5 + d'''
            simp [Nat.five_mul, Nat.mod_eq_self],
          }
        }
      }
    }
  }
end",
  "report": "Established the theorem by case analysis on n < 6, showing that for n = 0, 1, 2, 3, 4, 5, the square of n modulo 4 is 0."
}

